def sort_desc(arr: list) -> list:
    n = len(arr)
    for i in range(n - 1):
        for j in range(n - 1 - i):
            if compare(arr[j], arr[j + 1]) < 0:
                arr[j], arr[j + 1] = arr[j + 1], arr[j]
    return arr

def top_k(arr: list, k: int) -> list:
    if k <= 0:
        return []
    if k >= len(arr):
        return sort_desc(arr)
    sorted_arr = sort_desc(arr)
    return sorted_arr[:k]

